import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export default function StudentDashboard() {
  const [profile, setProfile] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [topUpAmount, setTopUpAmount] = useState('');
  const navigate = useNavigate();

  const fetchDashboardData = async () => {
    try {
      const { data } = await API.get('/users/profile');
      setProfile(data.user);
      setTransactions(data.transactions);
    } catch (error) {
      toast.error('Failed to load user profile');
      if (error.response?.status === 401) navigate('/');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const handleTopUp = async (e) => {
    e.preventDefault();
    try {
      const { data } = await API.post('/users/topup', { amountNaira: Number(topUpAmount) });
      toast.success(data.message);
      setTopUpAmount('');
      fetchDashboardData(); // Refresh balance
    } catch (error) {
      toast.error(error.response?.data?.message || 'Top-up failed');
    }
  };

  const handleLogout = async () => {
    await API.post('/auth/logout');
    localStorage.removeItem('userInfo');
    navigate('/');
  };

  if (loading) return <div className="min-h-screen flex items-center justify-center text-gray-500">Loading dashboard...</div>;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-4xl mx-auto space-y-6">
        
        {/* Header Section */}
        <div className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h1 className="text-2xl font-bold text-gray-900">{profile?.fullName}</h1>
            <p className="text-sm text-gray-500">{profile?.email} • {profile?.companyId?.name}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-2 bg-red-50 hover:bg-red-100 text-red-600 font-medium rounded-lg text-sm transition"
          >
            Sign Out
          </button>
        </div>

        {/* Balance Card & Top-Up */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-gray-900 text-white p-6 rounded-2xl shadow-md flex flex-col justify-between">
            <div>
              <p className="text-xs uppercase tracking-wider text-gray-400 font-semibold">Current Balance</p>
              <h2 className="text-4xl font-extrabold mt-2">{profile?.pointBalance} <span className="text-lg font-normal text-gray-300">Points</span></h2>
            </div>
            <p className="text-xs text-gray-400 mt-6">1 Point = ₦{profile?.companyId?.conversionRate || 50}</p>
          </div>

          <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
            <h3 className="text-lg font-bold text-gray-900 mb-3">Top-Up Wallet</h3>
            <form onSubmit={handleTopUp} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Amount in Naira (₦)</label>
                <input
                  type="number"
                  value={topUpAmount}
                  onChange={(e) => setTopUpAmount(e.target.value)}
                  placeholder="e.g. 2500"
                  required
                  className="w-full px-4 py-2 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
                />
              </div>
              <button
                type="submit"
                className="w-full py-2.5 bg-gray-900 hover:bg-gray-800 text-white font-medium rounded-lg text-sm transition shadow-sm"
              >
                Fund Account
              </button>
            </form>
          </div>
        </div>

        {/* Transaction History */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <h3 className="text-lg font-bold text-gray-900 mb-4">Transaction History</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-gray-100 text-xs uppercase tracking-wider text-gray-400">
                  <th className="py-3 px-4">Date</th>
                  <th className="py-3 px-4">Amount (₦)</th>
                  <th className="py-3 px-4">Points Deducted</th>
                  <th className="py-3 px-4">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50 text-sm text-gray-700">
                {transactions.length > 0 ? (
                  transactions.map((tx) => (
                    <tr key={tx._id} className="hover:bg-gray-50">
                      <td className="py-3 px-4">{new Date(tx.createdAt).toLocaleDateString()}</td>
                      <td className="py-3 px-4 font-medium">₦{tx.fiatAmount}</td>
                      <td className="py-3 px-4 text-red-600 font-semibold">-{tx.pointsDeducted} pts</td>
                      <td className="py-3 px-4">
                        <span className={`px-2.5 py-1 rounded-full text-xs font-medium ${
                          tx.status === 'completed' ? 'bg-green-50 text-green-700' : 
                          tx.status === 'pending' ? 'bg-yellow-50 text-yellow-700' : 'bg-red-50 text-red-700'
                        }`}>
                          {tx.status}
                        </span>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan="4" className="py-6 text-center text-gray-400">No transactions recorded yet.</td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>

      </div>
    </div>
  );
}
